// Writes pose_layer.json: inputs and expected outputs of the pose layer
// (poses.js applyPoseLayer), shared by tests/poses.test.mjs and the Go twin's
// test (demo/pose_layer_test.go), so both implementations stay identical.
//
// usage: node demo/editor/tests/fixtures/gen_pose_layer.mjs
// Regenerate only when the layer maths change on purpose (both sides at once).
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { applyPoseLayer } from '../../poses.js';
import { quatNormalize } from '../../math.js';

const here = path.dirname(fileURLToPath(import.meta.url));
const names = ['Hips', 'LeftArm', 'LeftForeArm', 'RightArm'];
const T = 7;

// Deterministic pseudo-random unit quaternions around a per-joint base, with
// sign flips (q and -q are the same rotation) to exercise the mean's alignment.
let seed = 12345;
const rnd = () => ((seed = (seed * 1103515245 + 12345) % 2147483648) / 2147483648) * 2 - 1;
const base = names.map(() => quatNormalize([rnd(), rnd(), rnd(), rnd() + 1.5]));
const local = [];
for (let t = 0; t < T; t++) {
  names.forEach((_, j) => {
    const spread = j === 3 ? 0.9 : 0.15; // RightArm swings far past the 10 degree clamp
    let q = quatNormalize(base[j].map((v) => v + spread * rnd()));
    if ((t + j) % 3 === 0) q = q.map((v) => -v);
    local.push(...q);
  });
}
const r6 = (v) => Math.round(v * 1e6) / 1e6;
const input = local.map(r6);
const target = (k) => quatNormalize([rnd(), rnd(), rnd(), rnd()]).map(r6);
const layers = [
  { mode: 'hold', joints: ['LeftArm', 'RightArm'], rotations: [target(), target()], strength: 0.75, sway: 0.5, max_sway_deg: 10 },
  { mode: 'hold', joints: ['LeftForeArm'], rotations: [target()] },
  { mode: 'hold', joints: ['LeftArm', 'LeftForeArm', 'RightArm'], rotations: [target(), target(), target()], strength: 1, sway: 0, max_sway_deg: 15 },
];
const cases = layers.map((layer) => ({
  layer,
  expected: Array.from(applyPoseLayer(Float32Array.from(input), T, names, layer)),
}));
const out = { _doc: 'Generated by gen_pose_layer.mjs (poses.js applyPoseLayer). rotations: [T][J] xyzw, row-major.', names, frames: T, rotations: input, cases };
fs.writeFileSync(path.join(here, 'pose_layer.json'), `${JSON.stringify(out, null, 1)}\n`);
console.log('wrote pose_layer.json');
